import { createServer, Server } from 'http';
import { promises as fs } from 'fs';
import * as path from 'path';
import chokidar from 'chokidar';
import { WebSocketServer, WebSocket } from 'ws';
import { build } from './generator';
import { BuildOptions } from './types';

const DEFAULT_PORT = 3000;
const LIVERELOAD_PATH = '/__ssg_livereload';
const REBUILD_DEBOUNCE_MS = 100;

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.htm': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.xml': 'application/xml; charset=utf-8',
  '.txt': 'text/plain; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.webp': 'image/webp',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.ttf': 'font/ttf',
  '.pdf': 'application/pdf',
  '.map': 'application/json',
};

export interface ServeOptions extends BuildOptions {
  port?: number;
}

export interface DevServer {
  server: Server;
  wss: WebSocketServer;
  port: number;
  close(): Promise<void>;
}

/**
 * Browser-side client that connects to the live-reload WebSocket endpoint and
 * reloads the page when a `reload` message arrives.
 */
export function reloadClientScript(): string {
  return `<script>
(function () {
  var reconnectDelay = 500;
  function connect() {
    var ws = new WebSocket((location.protocol === 'https:' ? 'wss://' : 'ws://') + location.host + '${LIVERELOAD_PATH}');
    ws.onmessage = function (event) {
      if (event.data === 'reload') {
        location.reload();
      }
    };
    ws.onopen = function () {
      reconnectDelay = 500;
    };
    ws.onclose = function () {
      setTimeout(connect, reconnectDelay);
      reconnectDelay = Math.min(reconnectDelay * 2, 10000);
    };
  }
  connect();
})();
</script>`;
}

/**
 * Inject the live-reload client script into an HTML document just before the
 * closing `</body>` tag.
 */
export function injectReloadScript(html: string): string {
  const bodyClose = html.lastIndexOf('</body>');
  if (bodyClose === -1) {
    return html + '\n' + reloadClientScript();
  }
  return (
    html.slice(0, bodyClose) + reloadClientScript() + '\n' + html.slice(bodyClose)
  );
}

function resolveFilePath(urlPath: string, outputDir: string): string | null {
  let pathname: string;
  try {
    pathname = decodeURIComponent(urlPath.split('?')[0]).split('#')[0];
  } catch {
    return null;
  }
  const root = path.resolve(outputDir);
  const clean = pathname.replace(/^\/+/, '');
  const candidate = path.resolve(root, clean);
  if (candidate !== root && !candidate.startsWith(root + path.sep)) {
    return null;
  }
  return candidate;
}

async function fileStat(target: string): Promise<{ isDirectory: boolean } | null> {
  try {
    const stat = await fs.stat(target);
    return { isDirectory: stat.isDirectory() };
  } catch {
    return null;
  }
}

async function serveFile(reqUrl: string, outputDir: string, res: import('http').ServerResponse): Promise<void> {
  const file = resolveFilePath(reqUrl, outputDir);
  if (!file) {
    res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
    res.end('Forbidden');
    return;
  }

  let target = file;
  let stat = await fileStat(target);
  if (stat && stat.isDirectory) {
    target = path.join(target, 'index.html');
    stat = await fileStat(target);
  }
  if (!stat) {
    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
    res.end('Not Found');
    return;
  }

  const ext = path.extname(target).toLowerCase();
  const data = await fs.readFile(target);
  if (ext === '.html') {
    const body = data.toString('utf8');
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    res.end(injectReloadScript(body));
    return;
  }
  res.writeHead(200, { 'Content-Type': MIME_TYPES[ext] ?? 'application/octet-stream' });
  res.end(data);
}

/**
 * Start a live-reload development server.
 *
 * Performs an initial build, serves the built site from `outputDir`, watches
 * `contentDir` and `templatesDir` for changes, rebuilds on change, and tells
 * connected browsers to reload once a rebuild finishes.
 */
export async function startDevServer(options: ServeOptions): Promise<DevServer> {
  const port = options.port ?? DEFAULT_PORT;
  const contentDir = options.contentDir;
  const outputDir = options.outputDir;
  const templatesDir = options.templatesDir ?? 'templates';

  await build({ contentDir, outputDir, templatesDir });

  const wss = new WebSocketServer({ noServer: true });

  const server = createServer((req, res) => {
    serveFile(req.url ?? '/', outputDir, res).catch(() => {
      res.writeHead(500, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Internal Server Error');
    });
  });

  server.on('upgrade', (req, socket, head) => {
    const pathname = (req.url ?? '').split('?')[0];
    if (pathname === LIVERELOAD_PATH) {
      wss.handleUpgrade(req, socket, head, (ws) => {
        wss.emit('connection', ws, req);
      });
    } else {
      socket.destroy();
    }
  });

  const broadcast = (message: string): void => {
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send(message);
      }
    }
  };

  const watcher = chokidar.watch([contentDir, templatesDir], {
    ignoreInitial: true,
    ignored: (watchedPath: string) => {
      const normalized = path.resolve(watchedPath);
      const out = path.resolve(outputDir);
      if (normalized === out || normalized.startsWith(out + path.sep)) {
        return true;
      }
      const segments = normalized.split(path.sep);
      if (segments.includes('node_modules')) {
        return true;
      }
      if (path.basename(normalized).startsWith('.')) {
        return true;
      }
      return false;
    },
  });
  watcher.on('error', () => {
    // Watcher errors are non-fatal for the dev server.
  });

  let timer: NodeJS.Timeout | null = null;
  let queue: Promise<void> = Promise.resolve();

  const rebuild = async (): Promise<void> => {
    try {
      await build({ contentDir, outputDir, templatesDir });
      broadcast('reload');
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      broadcast(JSON.stringify({ type: 'error', message }));
    }
  };

  watcher.on('all', () => {
    if (timer) {
      clearTimeout(timer);
    }
    timer = setTimeout(() => {
      timer = null;
      queue = queue.then(rebuild);
    }, REBUILD_DEBOUNCE_MS);
  });

  await new Promise<void>((resolve, reject) => {
    server.once('error', reject);
    server.listen(port, () => {
      server.removeListener('error', reject);
      resolve();
    });
  });

  const address = server.address();
  const actualPort = address && typeof address === 'object' ? address.port : port;

  return {
    server,
    wss,
    port: actualPort,
    close: async () => {
      if (timer) {
        clearTimeout(timer);
      }
      for (const client of wss.clients) {
        client.terminate();
      }
      await watcher.close();
      await new Promise<void>((resolve) => wss.close(() => resolve()));
      server.closeAllConnections();
      await new Promise<void>((resolve) => server.close(() => resolve()));
    },
  };
}

import { build } from './generator';
import { startDevServer } from './serve';
import { BuildOptions } from './types';

const DEFAULT_CONTENT_DIR = 'content';
const DEFAULT_OUTPUT_DIR = 'dist';
const DEFAULT_TEMPLATES_DIR = 'templates';
const DEFAULT_PORT = 3000;

export interface CliArgs {
  command: string;
  options: BuildOptions;
  port?: number;
}

function usage(): string {
  return `Usage: ssg <command> [options]

Commands:
  build   Build a static site from Markdown files
  serve   Run a live-reload development server

Options:
  --content <dir>   Content directory containing Markdown files (default: ./content)
  --output <dir>    Output directory for generated HTML (default: ./dist)
  --templates <dir> Templates directory with .hbs templates, layouts/, and partials/ (default: ./templates)
  --port <number>   Port for the dev server (default: 3000)
  --help            Show this help message`;
}

export function parseArgs(argv: string[]): CliArgs {
  const options: BuildOptions = {
    contentDir: DEFAULT_CONTENT_DIR,
    outputDir: DEFAULT_OUTPUT_DIR,
    templatesDir: DEFAULT_TEMPLATES_DIR,
  };
  let command = 'build';
  let port: number | undefined;
  let seenPositional = false;

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];

    if (arg === '--help' || arg === '-h') {
      throw new HelpError(usage());
    }

    const equalsIndex = arg.indexOf('=');
    const flag = equalsIndex === -1 ? arg : arg.slice(0, equalsIndex);
    const inlineValue = equalsIndex === -1 ? undefined : arg.slice(equalsIndex + 1);

    if (flag === '--content') {
      options.contentDir = inlineValue ?? argv[++i];
      if (!options.contentDir) {
        throw new Error('--content requires a directory argument');
      }
    } else if (flag === '--output') {
      options.outputDir = inlineValue ?? argv[++i];
      if (!options.outputDir) {
        throw new Error('--output requires a directory argument');
      }
    } else if (flag === '--templates') {
      options.templatesDir = inlineValue ?? argv[++i];
      if (!options.templatesDir) {
        throw new Error('--templates requires a directory argument');
      }
    } else if (flag === '--port') {
      const raw = inlineValue ?? argv[++i];
      if (!raw) {
        throw new Error('--port requires a number argument');
      }
      const parsed = Number(raw);
