const path = require('path'), os = require('os'), fs = require('fs'), http = require('http');
const { startDevServer } = require('./dist/serve.js');
(async () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'srv3-'));
  const contentDir = path.join(root, 'content');
  fs.mkdirSync(contentDir, { recursive: true });
  fs.writeFileSync(path.join(contentDir, 'hello.md'), ['---','title: Hello','---','# Hello','World'].join('\n'));
  const dev = await startDevServer({ contentDir, outputDir: path.join(root, 'dist'), templatesDir: path.join(root, 'templates'), port: 0 });
  console.log('port', dev.port);
  console.log('writing new.md immediately');
  fs.writeFileSync(path.join(contentDir, 'new.md'), '# New Page');
  setTimeout(async () => {
    http.get('http://localhost:' + dev.port + '/new.html', (res) => {
      let d=''; res.on('data',c=>d+=c); res.on('end', async () => {
        console.log('new.html status', res.statusCode, 'contains h1:', d.includes('<h1>New Page</h1>'));
        await dev.close();
        process.exit(0);
      });
    });
  }, 3000);
})();
"

input.command:
export PATH="$HOME/.nvm/versions/node/v20.20.2/bin:$PATH"; cd /tmp/story_90872217a453 && node -e "
const path = require('path'), os = require('os'), fs = require('fs');
const chokidar = require('chokidar');
const root = fs.mkdtempSync(path.join(os.tmpdir(), 'cw6-'));
const contentDir = path.join(root, 'content');
fs.mkdirSync(contentDir, { recursive: true });
fs.writeFileSync(path.join(contentDir, 'hello.md'), '# Hello');
const templatesDir = path.join(root, 'templates');
const outputDir = path.join(root, 'dist');
const ignored = (watchedPath) => {
  const normalized = path.resolve(watchedPath);
  const out = path.resolve(outputDir);
  if (normalized === out || normalized.startsWith(out + path.sep)) return true;
  const segments = normalized.split(path.sep);
  if (segments.includes('node_modules')) return true;
  if (path.basename(normalized).startsWith('.')) return true;
  return false;
};
const watcher = chokidar.watch([contentDir, templatesDir], { ignoreInitial: true, ignored });
watcher.on('error', () => {});
const events = [];
watcher.on('all', (e, p) => { console.log('EVENT', e, path.basename(p)); events.push(e); });
watcher.once('ready', () => {
  console.log('READY -> writing immediately');
  fs.writeFileSync(path.join(contentDir, 'new.md'), '# New');
});
setTimeout(() => { console.log('final events:', events); watcher.close(); process.exit(0); }, 2500);
"

