export PATH="$HOME/.nvm/versions/node/v20.20.2/bin:$PATH"; cd /tmp/story_90872217a453 && node -e "
const path = require('path'), os = require('os'), fs = require('fs');
const chokidar = require('chokidar');
function run(delay, label) {
  return new Promise((resolve) => {
    const root = fs.mkdtempSync(path.join(os.tmpdir(), 'cw7-'));
    const contentDir = path.join(root, 'content');
    fs.mkdirSync(contentDir, { recursive: true });
    fs.writeFileSync(path.join(contentDir, 'hello.md'), '# Hello');
    const templatesDir = path.join(root, 'templates');
    const w = chokidar.watch([contentDir, templatesDir], { ignoreInitial: true });
    const events = [];
    w.on('all', (e, p) => events.push(e));
    w.once('ready', () => {
      setTimeout(() => { fs.writeFileSync(path.join(contentDir, 'new.md'), '# New'); }, delay);
    });
    setTimeout(() => { console.log(label, 'delay', delay, 'events:', events); w.close().then(resolve); }, 2200);
  });
}
(async () => {
  await run(0, 'A');
  await run(50, 'B');
  await run(100, 'C');
  await run(200, 'D');
  process.exit(0);
})();
"

