export PATH="$HOME/.nvm/versions/node/v20.20.2/bin:$PATH"; cd /tmp/story_90872217a453 && node dist/cli.entry.js serve --content /tmp/ssg-e2e/content --output /tmp/ssg-e2e/dist --templates /tmp/ssg-e2e/templates --port 4311 > /tmp/ssg-e2e/serve2.log 2>&1 &
SRV_PID=$!
sleep 2
node -e "
const WebSocket = require('ws');
const ws = new WebSocket('ws://localhost:4311/__ssg_livereload');
const got = [];
ws.on('open', () => {
  console.log('ws open; touching about.md');
  const fs = require('fs');
  fs.writeFileSync('/tmp/ssg-e2e/content/about.md', '# About Updated\nNew text');
});
ws.on('message', (d) => { got.push(d.toString()); console.log('received:', d.toString()); ws.close(); process.exit(0); });
ws.on('error', (e) => { console.log('ws error', e.message); process.exit(1); });
setTimeout(() => { console.log('TIMEOUT; got:', got); process.exit(1); }, 8000);
"
kill $SRV_PID 2>/dev/null; wait $SRV_PID 2>/dev/null; echo "server stopped"

